<script lang="ts">import {request} from '$lib/session.svelte';let workshops=$state<any[]>([]);let error=$state('');let loading=$state(true);let form=$state({slug:'',display_name:'',country_code:'FR',time_zone:'Europe/Paris'});$effect(()=>{void load()});async function load(){try{workshops=await request<any[]>('/v1/workshops')}catch(e){error=String(e)}finally{loading=false}}async function create(){try{await request('/v1/workshops',{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify(form)});form={slug:'',display_name:'',country_code:'FR',time_zone:'Europe/Paris'};await load()}catch(e){error=String(e)}}</script>
<svelte:head><title>Your workshops · MakersBrain</title></svelte:head><div class="row"><div><h1>Your workshops</h1><p class="muted">People, access, documents, and service health.</p></div></div>{#if error}<p class="error">{error}</p>{/if}{#if loading}<p>Loading…</p>{:else}<div class="grid workshops">{#each workshops as workshop}<a class="card" href={`/workshops/${workshop.id}/members`}><div class="row"><strong>{workshop.display_name}</strong><span class="status">{workshop.status}</span></div><p class="muted">{workshop.role} · {workshop.plan}</p></a>{/each}<form class="card form" onsubmit={(e)=>{e.preventDefault();void create()}}><strong>Create a workshop</strong><label>Name<input bind:value={form.display_name} required/></label><label>Slug<input bind:value={form.slug} pattern={'[a-z0-9][a-z0-9-]{1,62}[a-z0-9]'} required/></label><button>Create and provision</button></form></div>{/if}
